async def act(page):
    import re

    # Helper to attempt closing a visible modal/overlay by common close button names
    async def try_close_overlay():
        # Common close labels: Close, close, ×, X, x, dismiss
        close_names = [re.compile(r"close", re.I), re.compile(r"dismiss", re.I), "×", "X", "x"]
        for name in close_names:
            try:
                # get_by_role accepts regex for name
                btn = page.get_by_role("button", name=name)
                count = await btn.count()
                if count > 0:
                    # Click the first matching button
                    await btn.nth(0).click()
                    # give a moment for overlay to disappear
                    try:
                        await page.wait_for_timeout(300)
                    except Exception:
                        pass
                    return True
            except Exception:
                # ignore and try next
                pass
        # Fallback: look for any role="dialog" with a button child that looks like close
        try:
            dialogs = page.get_by_role("dialog")
            dcount = await dialogs.count()
            for i in range(dcount):
                dialog = dialogs.nth(i)
                btns = dialog.get_by_role("button")
                bcount = await btns.count()
                for j in range(bcount):
                    try:
                        await btns.nth(j).click()
                        try:
                            await page.wait_for_timeout(300)
                        except Exception:
                            pass
                        return True
                    except Exception:
                        pass
        except Exception:
            pass
        return False

    # Attempt to close any overlay that's currently present
    await try_close_overlay()

    # Use the knowledge-base helper to perform the visible search. This is the preferred action.
    # If it fails (for example because the helper expects a complementary region that doesn't exist),
    # fall back to a manual, accessibility-role-centric approach.
    search_succeeded = False
    try:
        await create_curated_collection_by_search(page, "reveals", max_results=0, resolve_links=True)
        search_succeeded = True
    except Exception:
        # Helper failed; proceed to a manual search attempt below
        search_succeeded = False

    # If the helper failed, attempt a manual search using accessibility roles without navigating away.
    if not search_succeeded:
        # Ensure any overlay is dismissed before interacting
        await try_close_overlay()

        # Locate a search input: prefer role="searchbox", else a textbox labelled Search
        search_input = None
        try:
            inp = page.get_by_role("searchbox")
            if await inp.count() > 0:
                search_input = inp.nth(0)
        except Exception:
            search_input = None

        if search_input is None:
            try:
                # Look for a textbox inside a complementary region
                comp = page.get_by_role("complementary")
                if await comp.count() > 0:
                    # prefer a searchbox then a textbox inside the complementary region
                    try:
                        sb = comp.get_by_role("searchbox")
                        if await sb.count() > 0:
                            search_input = sb.nth(0)
                    except Exception:
                        pass
                    if search_input is None:
                        try:
                            tb = comp.get_by_role("textbox")
                            if await tb.count() > 0:
                                search_input = tb.nth(0)
                        except Exception:
                            pass
            except Exception:
                pass

        # As a last resort, find any textbox with a name that includes "search"
        if search_input is None:
            try:
                tb = page.get_by_role("textbox", name=re.compile(r"search", re.I))
                if await tb.count() > 0:
                    search_input = tb.nth(0)
            except Exception:
                pass

        if search_input is None:
            # Could not find any accessible search input; abort with an informative exception
            raise Exception("Search input not found on page; cannot perform search for 'reveals'.")

        # Fill the search term and trigger the search. Prefer clicking a button inside the same complementary region.
        await search_input.fill("reveals")

        triggered = False
        # Try to find a button labeled Search inside the complementary region that contains this input
        try:
            # Ascend to complementary region if possible
            parent_comp = None
            try:
                comp = page.get_by_role("complementary")
                if await comp.count() > 0:
                    parent_comp = comp.nth(0)
            except Exception:
                parent_comp = None

            if parent_comp is not None:
                # Prefer a button whose name includes 'search'
                try:
                    search_btn = parent_comp.get_by_role("button", name=re.compile(r"search", re.I))
                    if await search_btn.count() > 0:
                        await search_btn.nth(0).click()
                        triggered = True
                except Exception:
                    pass

                if not triggered:
                    # Click the first button inside the complementary region
                    try:
                        first_btn = parent_comp.get_by_role("button")
                        if await first_btn.count() > 0:
                            await first_btn.nth(0).click()
                            triggered = True
                    except Exception:
                        pass
        except Exception:
            pass

        if not triggered:
            # As a last resort, press Enter in the input
            await search_input.press("Enter")

        # Wait for results: prefer main role to become visible
        try:
            await page.get_by_role("main").wait_for(state="visible", timeout=5000)
        except Exception:
            # Fallback to networkidle
            await page.wait_for_load_state("networkidle")

    # At this point search results should be rendered inside role="main" as role="article" children.
    main = page.get_by_role("main")
    try:
        await main.wait_for(state="visible", timeout=3000)
    except Exception:
        # If main isn't visible yet, give a short pause
        await page.wait_for_load_state("networkidle")

    articles = main.get_by_role("article")
    article_count = await articles.count()
    if article_count < 3:
        raise Exception(f"Expected at least 3 search results, found {article_count}")

    # Select the third article (index 2)
    third_article = articles.nth(2)

    # Try to click a link inside the third article via the full path
    links_in_third = third_article.get_by_role("link")
    if await links_in_third.count() > 0:
        await links_in_third.nth(0).click()
        return

    # Fallback: click a heading inside the article
    headings_in_third = third_article.get_by_role("heading")
    if await headings_in_third.count() > 0:
        await headings_in_third.nth(0).click()
        return

    # Last resort: click the article container itself
    await third_article.click()

